// fakeSearch stands in for the cmd/mellifera closure over
// Queue.SearchSource: it records every call and replays the canned
// candidates/err. The pacing gate and the plugin resolution live cmd-side —
// this fake is the seam the handler contract is pinned against.
func fakeSearch(cands []map[string]any, err error, calls *[]searchCall) func(context.Context, string, string, string) ([]map[string]any, error) {
	return func(_ context.Context, pluginID, query, kind string) ([]map[string]any, error) {
		*calls = append(*calls, searchCall{pluginID: pluginID, query: query, kind: kind})
		return cands, err
	}
}

